CREATE VIEW insightsbi.vwAD_RTF_PRODUCT_BOOKING_ROLLUP AS

/*
Columns:
Source Platform (eg OLA, CE)
Product Type (eg Webinar, Training course)
Product Group (eg DRS, Regs)
Event Type (eg Face to Face, Online)
Course Name
EVENTID
SKU
Event Start Date
Event End Date
Event Length
Region
Max CapaciTY
Sales (LOCAL CURRENCY)
Revenue (in GBP)
Orders (split by region?)
Qty Sold (split by region)
Future event?
Potential Revenue
Revenue Achieved
*/

WITH CE_BOOKINGS AS (
SELECT 
SOURCE_PLATFORM
,PRODUCT_TYPE
,PRODUCT_GROUP
,EVENT_TYPE
,COURSE_NAME
,EVENT_ID
,SKU_CODE
,EVENT_START_DATE
,EVENT_LENGTH
,EVENT_COUNTRY
,FUTURE_EVENT
,MAX(MAX_CAPACITY) AS MAX_CAPACITY
,COUNT(DISTINCT(BOOKING_ID)) AS TOTAL_BOOKINGS
,COUNT(DISTINCT(CAMPAIGN_RESPONSE_KEY)) AS TOTAL_QTY_SOLD
,SUM(TOTAL_COST_GBP) AS TOTAL_REVENUE_GBP
,SUM(NET_COST_GBP) AS TOTAL_NET_REVENUE_GBP
,SUM(TAX_COST_GBP) AS TOTAL_TAX_GBP
,CASE 
	WHEN COUNT(BOOKING_ID) >0 THEN (SUM(TOTAL_COST_GBP)/COUNT(DISTINCT(CAMPAIGN_RESPONSE_KEY))) * MAX(MAX_CAPACITY) 
	ELSE 0 
	END AS POTENTIAL_REVENUE_GBP
,CASE 
	WHEN COUNT(BOOKING_ID) >0 THEN (SUM(NET_COST_GBP)/COUNT(DISTINCT(CAMPAIGN_RESPONSE_KEY))) * MAX(MAX_CAPACITY) 
	ELSE 0 
	END AS POTENTIAL_NET_REVENUE_GBP
,CASE 
	WHEN COUNT(BOOKING_ID) >0 THEN (SUM(TAX_COST_GBP)/COUNT(DISTINCT(CAMPAIGN_RESPONSE_KEY))) * MAX(MAX_CAPACITY) 
	ELSE 0 
	END AS POTENTIAL_TAX_GBP



FROM InsightsBI.vwAD_Product_Bookings_CE

GROUP BY 
SOURCE_PLATFORM
,PRODUCT_TYPE
,PRODUCT_GROUP
,EVENT_TYPE
,COURSE_NAME
,EVENT_ID
,SKU_CODE
,EVENT_START_DATE
,EVENT_LENGTH
,EVENT_COUNTRY
,FUTURE_EVENT

),

EVENTBRITE_BOOKINGS AS (
SELECT 
'Eventbrite' AS SOURCE_PLATFORM
,A.PRODUCT_TYPE
,PRODUCT_GROUP
,EVENT_TYPE
,A.COURSE_NAME
,EVENT_ID
,CAST(A.SKU_CODE AS VARCHAR) AS SKU_CODE
,A.EVENT_START_DATE
,CAST(A.EVENT_LENGTH AS INT) AS EVENT_LENGTH
,CAST(A.EVENT_COUNTRY AS VARCHAR) AS EVENT_COUNTRY
,A.FUTURE_EVENT
,MAX(a.MAX_CAPACITY) AS MAX_CAPACITY
,COUNT(DISTINCT(BOOKING_ID)) AS TOTAL_BOOKINGS
,COUNT(DISTINCT(CAMPAIGN_RESPONSE_KEY)) AS TOTAL_QTY_SOLD
,SUM(TOTAL_COST_GBP) AS TOTAL_REVENUE_GBP
,SUM(NET_COST_GBP) AS TOTAL_NET_REVENUE_GBP
,SUM(TAX_COST_GBP) AS TOTAL_TAX_GBP
,CASE 
	WHEN COUNT(BOOKING_ID) >0 THEN (SUM(TOTAL_COST_GBP)/COUNT(DISTINCT(CAMPAIGN_RESPONSE_KEY))) * MAX(MAX_CAPACITY) 
	ELSE 0 
	END AS POTENTIAL_REVENUE_GBP
,CASE 
	WHEN COUNT(BOOKING_ID) >0 THEN (SUM(NET_COST_GBP)/COUNT(DISTINCT(CAMPAIGN_RESPONSE_KEY))) * MAX(MAX_CAPACITY) 
	ELSE 0 
	END AS POTENTIAL_NET_REVENUE_GBP
,CASE 
	WHEN COUNT(BOOKING_ID) >0 THEN (SUM(TAX_COST_GBP)/COUNT(DISTINCT(CAMPAIGN_RESPONSE_KEY))) * MAX(MAX_CAPACITY) 
	ELSE 0 
	END AS POTENTIAL_TAX_GBP

from InsightsBI.vwAD_PRODUCT_BOOKINGS_EVENTBRITE as a

--left join  [EventBrite].[vwEventTicketReport] as b
--on a.course_name = b.[Event Name]

GROUP BY SOURCE_PLATFORM
,PRODUCT_TYPE
,PRODUCT_GROUP
,EVENT_TYPE
,COURSE_NAME
,EVENT_ID
,SKU_CODE
,EVENT_START_DATE
,EVENT_LENGTH
,EVENT_COUNTRY
,FUTURE_EVENT


)

SELECT
*
FROM CE_BOOKINGS
where EVENT_ID is not null 
UNION ALL
SELECT
*
FROM EVENTBRITE_BOOKINGS
where EVENT_ID is not null
